    {"name":"kompas_component_transform","description":"Set one exact assembly component to an absolute rigid transform represented by origin plus orthonormal X/Y/Z axes. Rejects non-finite values, scale, shear, and reflection; requires determinant +1; snapshots exact assembly bytes; checks exact active PathName before write and Save; then verifies native origin, axes, 4x4 matrix, bbox, source reference, and Save->Close->Reopen persistence.","inputSchema":{"type":"object","required":["assembly_filename","selector","origin","axis_x","axis_y","axis_z"],"properties":{"assembly_filename":{"type":"string","minLength":1},"selector":{"oneOf":[{"type":"integer","minimum":0},{"type":"string","minLength":1},{"type":"array","items":{"type":"integer","minimum":0},"minItems":1}]},"origin":{"type":"array","items":{"type":"number"},"minItems":3,"maxItems":3},"axis_x":{"type":"array","items":{"type":"number"},"minItems":3,"maxItems":3},"axis_y":{"type":"array","items":{"type":"number"},"minItems":3,"maxItems":3},"axis_z":{"type":"array","items":{"type":"number"},"minItems":3,"maxItems":3},"mode":{"type":"string","enum":["absolute"],"default":"absolute"}},"additionalProperties":False},"annotations":{"readOnlyHint":False,"destructiveHint":False,"idempotentHint":True}},
    {"name":"kompas_material_read","description":"Read native material name, density, and mass from one existing .m3d under approved work, including nested read-only evidence sources. Opens the exact file, performs no Save, closes it, and restores the prior AGENT_COPY.","inputSchema":{"type":"object","required":["relative_path"],"properties":{"relative_path":{"type":"string","minLength":1}},"additionalProperties":False},"annotations":{"readOnlyHint":True}},
    {"name":"kompas_material_set","description":"Set native material on one direct-work *_AGENT_COPY.m3d using API7 IPart7.SetMaterial. The requested material name and positive density must exactly match a separately read native evidence-source .m3d under approved work. Performs byte snapshot rollback, exact active-path checks, before/after name-density-mass readback, Save->Close->Reopen verification, and prior active-document restore.","inputSchema":{"type":"object","required":["filename","material_name","density","evidence_source_relative_path"],"properties":{"filename":{"type":"string","minLength":1},"material_name":{"type":"string","minLength":1},"density":{"type":"number","exclusiveMinimum":0},"evidence_source_relative_path":{"type":"string","minLength":1}},"additionalProperties":False},"annotations":{"readOnlyHint":False,"destructiveHint":False,"idempotentHint":True}},
    {"name":"kompas_pmi_read","description":"Read structured native KOMPAS 3D PMI dimensions from API7 ISymbols3DContainer collections. Returns dimension kind/value, model-object association, text position, and text/tolerance fields where the concrete COM object exposes them. Floating ModelTexts are deliberately excluded and never counted as PMI dimensions.","inputSchema":{"type":"object","properties":{"max_dimensions":{"type":"integer","minimum":1,"maximum":2000,"default":500}},"additionalProperties":False},"annotations":{"readOnlyHint":True}},
    {"name":"kompas_pmi_dimension_create","description":"Create one real native geometry-linked API7 ILineDimension3D between two exact existing vertices on XOY in a closed direct-work *_AGENT_COPY.m3d. Uses native Object1/Object2 links and text position, transaction snapshot rollback, exact-path checks, and Save->Close->Reopen validation of count, validity, geometry links, and nominal value. Coordinate/baseline, diameter, and radius families are deliberately not simulated.","inputSchema":{"type":"object","required":["filename","point1","point2","text_position"],"properties":{"filename":{"type":"string","minLength":1},"point1":{"type":"array","items":{"type":"number"},"minItems":3,"maxItems":3},"point2":{"type":"array","items":{"type":"number"},"minItems":3,"maxItems":3},"text_position":{"type":"array","items":{"type":"number"},"minItems":3,"maxItems":3},"plane":{"type":"string","enum":["XOY"],"default":"XOY"},"name":{"type":"string","minLength":1,"maxLength":80,"default":"CAP2_LINEAR_DIMENSION"},"point_tolerance":{"type":"number","exclusiveMinimum":0,"maximum":1,"default":0.001}},"additionalProperties":False},"annotations":{"readOnlyHint":False,"destructiveHint":False,"idempotentHint":False}},
