    {"name":"kompas_component_properties_set","description":"Set only proven native writable API7 IPart7 occurrence fields Name and Marking/designation in a closed direct-work *_AGENT_COPY.a3d. Requires at least one value; preserves external source reference and bytes; snapshots assembly; verifies before/requested/after and Save->Close->Reopen persistence; restores the prior active AGENT_COPY.","inputSchema":{"type":"object","required":["assembly_filename","selector"],"properties":{"assembly_filename":{"type":"string","minLength":1},"selector":{"oneOf":[{"type":"integer","minimum":0},{"type":"string","minLength":1},{"type":"array","items":{"type":"integer","minimum":0},"minItems":1}]},"designation":{"type":"string","minLength":1,"maxLength":200},"name":{"type":"string","minLength":1,"maxLength":200}},"anyOf":[{"required":["designation"]},{"required":["name"]}],"additionalProperties":False},"annotations":{"readOnlyHint":False,"destructiveHint":False,"idempotentHint":True}},
