    {"name":"kompas_mate_read","description":"Read the mate constraints of the active assembly through the native IMateConstraint collection: kind, direction, numeric value, fixed flag and participant names. Call it before adding mates so you work from the real constraint set. Reports which interface name actually resolved, and returns interface.confirmed=false instead of an empty list when no known collection name matched.","inputSchema":{"type":"object","properties":{"max_items":{"type":"integer","minimum":1,"maximum":2000,"default":200}},"additionalProperties":False},"annotations":{"readOnlyHint":True}},
    {"name":"kompas_mate_create","description":"Create exactly ONE native mate constraint between two existing components of a closed direct-work *_AGENT_COPY.a3d. kind=distance or angle require value in mm or degrees; coincident, parallel, perpendicular, concentric and tangent must not carry a value. Performs a byte transaction snapshot, exact active-path checks, mate-count growth check, Save->Close->Reopen persistence verification, and restores the previously active document. Refuses with mate_create_interface_not_available when no known create method resolves, instead of reporting success.","inputSchema":{"type":"object","required":["assembly_filename","kind","selector_a","selector_b"],"properties":{"assembly_filename":{"type":"string","minLength":1},"kind":{"type":"string","enum":["coincident","parallel","perpendicular","concentric","tangent","distance","angle"]},"selector_a":{"oneOf":[{"type":"integer","minimum":0},{"type":"string","minLength":1},{"type":"array","items":{"type":"integer","minimum":0},"minItems":1}]},"selector_b":{"oneOf":[{"type":"integer","minimum":0},{"type":"string","minLength":1},{"type":"array","items":{"type":"integer","minimum":0},"minItems":1}]},"value":{"type":"number","exclusiveMinimum":0},"align":{"type":"string","enum":["aligned","opposite","auto"],"default":"auto"},"fixed":{"type":"boolean","default":False}},"additionalProperties":False},"annotations":{"readOnlyHint":False,"destructiveHint":False,"idempotentHint":False}},
    {"name":"kompas_artifact_check","description":"Verify an exported artifact by its content instead of trusting that the export call returned without error: STEP header/end markers plus entity and solid counts, DXF sections plus entity count, PDF page count, PNG dimensions. Use it after any export or kompas_run_job that produced a file, because a failed KOMPAS export normally raises nothing at all.","inputSchema":{"type":"object","required":["relative_path"],"properties":{"relative_path":{"type":"string","minLength":1}},"additionalProperties":False},"annotations":{"readOnlyHint":True}},
