    {"name":"kompas_open_copy","description":"Create a disposable working COPY and open it as the active visible writable KOMPAS document. Source is never edited directly. Omit source to use the active document. name must be a filename only.","inputSchema":{"type":"object","properties":{"source":{"type":"string"},"name":{"type":"string"}},"additionalProperties":False},"annotations":{"readOnlyHint":False,"destructiveHint":False,"idempotentHint":False}},
